import { z } from 'zod';

/** Every entity id is a UUID (version 7, generated by the service). */
export const Uuid = z.uuid().meta({
  description: 'Resource identifier (UUID).',
  example: '0199d1e2-7b3a-7c41-9a51-2f3e8c4d5a10',
});

export const IsoDateTime = z.iso.datetime().meta({
  description: 'ISO-8601 timestamp in UTC.',
  example: '2026-10-10T12:00:00.000Z',
});

export const Money = z
  .object({
    amountMinor: z.int().min(0).meta({
      description: 'Amount in minor currency units (e.g. cents). Never a float.',
      example: 1999,
    }),
    currency: z
      .string()
      .regex(/^[A-Z]{3}$/)
      .meta({ description: 'ISO 4217 currency code.', example: 'USD' }),
  })
  .meta({ id: 'Money' });
export type Money = z.infer<typeof Money>;

export const IdParams = z.strictObject({ id: Uuid });
export type IdParams = z.infer<typeof IdParams>;
